INSERT INTO "成果论文" ("编号", "认领人编号", "论文标题", "论文标题类型", "论文Online日期", "论文正式出版日期", "他引次数", "年度", "收稿日期", "论文所属栏目", "版面费", "超额版面费", "超额费用来源", "奖励情况", "论文字数", "计划来源", "论文版面", "学科门类", "一级学科", "二级学科", "三级学科", "作者人数", "关键字", "论文摘要", "备注", "刊物编号", "卷号", "期号", "页码范围起", "页码范围止", "论文类型", "是否与行业联合发表", "是否与地方联合发表", "是否与国际联合发表", "是否跨学科", "是否与本专业相关", "检索信息页相关文件路径", "论文正文路径", "其他相关文件路径") VALUES
(5, 2, E'string', E'string', E'2018-05-25', E'2018-05-25', 0, 0, E'2018-05-25', E'string', 0.0, 0.0, E'string', E'string', 0.0, E'string', E'string', E'string', E'string', E'string', E'string', 0, E'string', E'string', E'string', 0, 0, 0, 0, 0, E'string', TRUE, TRUE, TRUE, TRUE, TRUE, E'string', E'string', E'string'),
(6, NULL, E'河北省葡萄产区土壤中微量元素分布特征及其对果实品质的影响', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 4, E'中微量元素;;分布特征;;品质;;葡萄;;河北省', E'在河北省昌黎县、涿鹿县、怀来县3个葡萄产区选取赤霞珠(酿酒)、红地球(鲜食)、龙眼(鲜食)葡萄园共120个,于葡萄成熟期时分别采集0~20、21~40、41~60cm土壤及果实样品,测定土壤、果实中的中微量元素含量及葡萄果实品质,分析河北省葡萄产区土壤中微量元素分布特征及其对果实品质的影响。结果表明,3县葡萄园土壤的交换性Ca、Mg含量分别在0.216%~0.664%、0.030%~0.076%之间,均处于丰富水平;昌黎县葡萄园土壤有效Fe含量丰富,涿鹿县、怀来县适量;3个县葡萄园土壤有效Mn含量处于低或缺乏水平,有效Cu含量为丰富状态,有效Zn含量整体为适量水平;怀来县葡萄园区土壤有效B含量较低,其他2个县均为适量水平;葡萄果实中的中微量元素含量均较丰富,其中,Ca、Mg含量分别达到485.89、394.69mg/kg;酿酒葡萄中的固酸比显著高于鲜食葡萄;除土壤中的有效Cu、有效B外,其他土壤中微量元素与果实中相应的元素含量均呈显著正相关;赤霞珠葡萄园的土壤有效B含量与果实单粒质量、pH值、维生素C含量呈正相关,与可溶性固形物含量、酒石酸含量、固酸比呈负相关;红地球、龙眼葡萄园土壤中有效B含量与果实单粒质量、pH值、维生素C含量呈正相关,其他元素均与果实单粒质量、pH值、可溶性固形物含量呈负相关或不明显正相关。因此,应因地制宜施用中微量元素肥料,建议增施Mn、B等肥料,降低Ca、Mg肥的用量,减少含铜杀菌剂的使用。', NULL, 11351, NULL, NULL, 1, 5, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7, NULL, E'黑龙江省主栽水稻品种对稻瘟病的抗性评价与利用', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 7, E'黑龙江省;;水稻品种;;稻瘟病;;抗性频率;;联合抗病性系数;;抗性评价;;可利用价值评价', E'用水稻苗期接种稻瘟病病菌的方法,测定23个黑龙江省主栽水稻品种对黑龙江省5个水稻主要种植区的180个稻瘟病病菌菌株的抗性频率和联合抗病性系数。结果表明,供试的水稻品种对供试菌株的抗性总体表现较好,具有差异,平均抗性频率为78.03%,抗性频率最低的是龙粳21,最高的是龙粳42,差距达1.75倍。通过对品种组合联合抗病性系数分析可知,23个品种组合的联合抗病性系数(pathogenicity association coefficient,简称RAC)有差异,2个品种组合RAC最高的品种是龙粳42和龙粳40,最低的是龙粳21和龙粳29。', NULL, 11351, NULL, NULL, 1, 4, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(12, NULL, E'论文标题示例', E'中文', E'2018-06-01', E'2018-06-01', 100, 2018, E'2018-06-01', E'临床研究', NULL, NULL, NULL, NULL, 20.5, E'863计划', E'正常版面', E'医学', E'临床医学', E'内科学', E'呼吸病学', 2, E'中微量元素;;分布特征;;品质;;葡萄;;河北省', E'在河北省昌黎县、涿鹿县、怀来县3个葡萄产区选取赤霞珠(酿酒)、红地球(鲜食)、龙眼(鲜食)葡萄园共120个,于葡萄成熟期时分别采集0~20、21~40、41~60cm土壤及果实样品,测定土壤、果实中的中微量元素含量及葡萄果实品质,分析河北省葡萄产区土壤中微量元素分布特征及其对果实品质的影响。结果表明,3县葡萄园土壤的交换性Ca、Mg含量分别在0.216%~0.664%、0.030%~0.076%之间,均处于丰富水平;昌黎县葡萄园土壤有效Fe含量丰富,涿鹿县、怀来县适量;3个县葡萄园土壤有效Mn含量处于低或缺乏水平,有效Cu含量为丰富状态,有效Zn含量整体为适量水平;怀来县葡萄园区土壤有效B含量较低,其他2个县均为适量水平;葡萄果实中的中微量元素含量均较丰富,其中,Ca、Mg含量分别达到485.89、394.69mg/kg;酿酒葡萄中的固酸比显著高于鲜食葡萄;除土壤中的有效Cu、有效B外,其他土壤中微量元素与果实中相应的元素含量均呈显著正相关;赤霞珠葡萄园的土壤有效B含量与果实单粒质量、pH值、维生素C含量呈正相关,与可溶性固形物含量、酒石酸含量、固酸比呈负相关;红地球、龙眼葡萄园土壤中有效B含量与果实单粒质量、pH值、维生素C含量呈正相关,其他元素均与果实单粒质量、pH值、可溶性固形物含量呈负相关或不明显正相关。因此,应因地制宜施用中微量元素肥料,建议增施Mn、B等肥料,降低Ca、Mg肥的用量,减少含铜杀菌剂的使用。', NULL, 10010, 1, 1, NULL, NULL, E'学位论文', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
