(230001, E'社会经济目标分类', E'能源生产、分配和合理利用', 0, 1, 0, NULL),
(230002, E'社会经济目标分类', E'卫生事业发展', 0, 1, 0, E'有关军事医学的内容归入1303'),
(230003, E'社会经济目标分类', E'教育事业发展', 0, 1, 0, NULL),
(230004, E'社会经济目标分类', E'基础设施以及城市和农村规划', 0, 1, 0, NULL),
(230005, E'社会经济目标分类', E'社会发展和社会服务', 0, 1, 0, NULL),
(230006, E'社会经济目标分类', E'地球和大气层的探索与利用', 0, 1, 0, NULL),
(230007, E'社会经济目标分类', E'民用空间探测及开发', 0, 1, 0, NULL),
(230008, E'社会经济目标分类', E'农林牧渔业发展', 0, 1, 0, E'包括直接以促进农、林、牧、渔业发展为目标的所有科学技术活动'),
(230009, E'社会经济目标分类', E'工商业发展', 0, 1, 0, E'包括以促进和发展工业、建筑业、信息与通信技术服务业、技术服务业、金融业、仓储业、批发和零售业、住宿、旅游和餐饮服务业为目标的所有科学技术活动。但工业中涉及能源资源的矿产开采和涉及电力、燃气等有关能源生产、输配的活动归入02大类'),
(230010, E'社会经济目标分类', E'非定向研究', 0, 1, 0, E'此类仅包括各学科的基础理论研究，不包括针对某一特定实际应用目的或目标的研究'),
(230011, E'社会经济目标分类', E'其他民用目标', 0, 1, 0, E'前述11大类未包括的民用领域的研究'),
(230012, E'社会经济目标分类', E'国防', 0, 1, 0, E'只包括以国防为主要目的（可以有次要的民用目的）所进行的研究。国防部门或军事机构进行的以民用为主要目的的研究不属此类，应归入相应的民用目标。'),
(230013, E'社会经济目标', E'环境一般问题', 230000, 2, 0, E'环境政策、立法与标准；经济、社会发展对环境的影响；生活方式、消费行为对环境的影响；制度安排、经济制约与环境保护；环境教育和环境知识；环境变化对人类及其他物种的影响；其他环境一般问题'),
(230014, E'社会经济目标', E'环境与资源评估', 230000, 2, 0, E'综合生态系统评估与保护；全球气候变化检测与影响评估；气候变化和海洋变化相互作用；环境与自然资源的恢复；环境质量及环境功能区划分；环境与资源评估的其他研究'),
(230016, E'社会经济目标', E'环境监测', 230000, 2, 0, E'环境监控、测量方法；环境监控网络的建立；环境监控、测量工具的研制；其他环境监测'),
(230017, E'社会经济目标', E'生态建设', 230000, 2, 0, E'河流与湖泊；陆地；海洋；大气；自然和半自然生态系统的保护、监测和多样性（包括各类生态保护区、湿地、野生植物群和动物群以及他们的栖息地）；生态工程；其他生态建设'),
(230018, E'社会经济目标', E'环境污染预防', 230000, 2, 0, E'废气、废水、废物的减排与处理；放射物对人类和物种的影响及污染预防（包括放射物的监测、运输、储存、废弃物管理等）；光、声、电污染的影响、测量及预防；电磁辐射的影响、测量及污染预防；环境污染事故的预防与应急处理；其他环境污染预防'),
(230019, E'社会经济目标', E'环境治理', 230000, 2, 0, E'污染源的排除和污染区域的治理（包括化学的、物理的和生物的污染）；恶化、退化环境的治理与复原；有害物与外来物种控制；其他环境治理'),
(230020, E'社会经济目标', E'自然灾害的预防、预报', 230000, 2, 0, E'气象灾害（包括热带风暴、龙卷风、雷暴大风、暴风雪、暴雨、寒潮、冷害、霜冻、雹灾及旱灾等）；洪水灾害（包括洪涝灾害、江河泛滥等）；地震；崩塌、滑坡和泥石流；地面塌陷、地裂缝和地面沉降；土地沙化、荒漠化和石漠化；沙尘暴；赤潮；其他自然灾害的预防、预报'),
(230021, E'社会经济目标', E'能源一般问题研究', 230001, 2, 0, E'能源产业政策、发展战略和规划；能源储备、供给与需求；能源管理系统和方法；其他能源一般问题研究'),
(230022, E'社会经济目标', E'能源矿产勘探技术', 230001, 2, 0, E'煤的勘探；煤层气的勘探；石油和天然气勘探；铀的勘探；其他能源矿产勘探'),
(230023, E'社会经济目标', E'能源矿物开采和加工技术', 230001, 2, 0, E'煤的开采、加工和运送技术；煤层气的开采和运送技术；石油和天然气开采；深井钻探；矿物气化、液化、精炼和脱硫；精炼石油产品制造（包括原油加工及石油制品制造、人造原油生产）；炼焦；核燃料加工；其他能源矿物开采和加工'),
(230024, E'社会经济目标', E'能源转换技术', 230001, 2, 0, E'煤——电；煤——液体燃料；煤——其他用途；原子能；精制石油——天然气；天然气——液体燃料；核能——电；废物废料处理转化成能源；其他能源转换'),
(230025, E'社会经济目标', E'能源输送、储存与分配技术', 230001, 2, 0, E'能源输送、储存与分配系统性分析；能源储存；输配电和电网安全；石油和天然气输送；其他能源输送、储存与分配'),
(230026, E'社会经济目标', E'可再生能源', 230001, 2, 0, E'可再生能源的资源调查、分析和评估；水能；风能；潮汐能；太阳——热能；太阳——光电；太阳——热电；地热能；生物质热、电、液体燃料转换与利用；其他可再生能源'),
(230027, E'社会经济目标', E'能源设施和设备建造', 230001, 2, 0, E'包括所有与能源开采、输配、储存、利用有关的设施和大型设备的研究和建造技术：火力发电设施（包括燃煤发电、天然气发电及其他火力发电）；水力发电设施；核电站；风力发电设施；输配电设施；石油钻探平台；输油管道和储油设施；铀矿开采设备和设施；煤矿开采设备和设施；其他能源设施和设备建造'),
(230028, E'社会经济目标', E'能源安全生产管理和技术', 230001, 2, 0, E'煤矿安全生产；石油和天然气安全生产；核电站安全生产；其他能源安全生产管理和技术'),
(230029, E'社会经济目标', E'节约能源的技术', 230001, 2, 0, E'建筑物和商业节能（包括住宅节能）；工业节能；交通运输节能；能源输送损耗的减少；其他节约能源的技术'),
(230030, E'社会经济目标', E'能源生产、输送、分配、储存、利用过程中污染的防治与处理', 230001, 2, 0, NULL),
(230031, E'社会经济目标', E'卫生一般问题', 230002, 2, 0, E'医疗卫生相关政策；医疗卫生体系；其他卫生一般问题');
INSERT INTO "字典" ("编号", "分类", "值", "上级编号", "级别", "排序", "备注") VALUES
(230032, E'社会经济目标', E'诊断与治疗', 230002, 2, 0, E'诊断方法与技术的发展；治疗方法与技术的发展；特定疾病的研究（如癌症、心血管疾病、暴发性传染病、血吸虫病、精神疾病等）；器官移植；矫形；护理技术；康复医学与康复工程；特殊治疗；中医与中药治疗方法及治病机理（中药制造归入1006）；其他诊断与治疗'),
(230033, E'社会经济目标', E'预防医学', 230002, 2, 0, E'流行病学；疾病的早期诊断及预防性治疗；一般性预防方法、疫苗研制和接种；疾病传播控制；其他预防医学'),
(230034, E'社会经济目标', E'公共卫生', 230002, 2, 0, E'心理卫生；环境卫生；职业病防治；保健；卫生教育和宣传；其他公共卫生'),
(230035, E'社会经济目标', E'营养和食品卫生', 230002, 2, 0, E'人类营养学；食品卫生；其他营养和食品卫生'),
(230036, E'社会经济目标', E'药物滥用和成瘾', 230002, 2, 0, E'药物成瘾风险；食物、毒品和滥用药物引起的中毒；药物使用不当引发的耐药性；其他药物滥用和成瘾'),
(230037, E'社会经济目标', E'社会医疗', 230002, 2, 0, E'医疗保障体系；社区医疗；农村医疗；其他社会医疗'),
(230038, E'社会经济目标', E'卫生医疗其他研究', 230002, 2, 0, E'药物检验监督制度与方法；药品不良反应（为研制新药进行的药物不良反应研究归入1006）；医疗事故鉴定；生殖生育；其他卫生医疗研究'),
(230039, E'社会经济目标', E'教育一般问题', 230003, 2, 0, E'教育制度与政策（包括农村教育制度与政策）；教育管理；教育方法；其他教育一般问题'),
(230040, E'社会经济目标', E'学历教育', 230003, 2, 0, E'初等教育（小学教育）；中等教育（初中教育、高中教育、中等专业教育、职业中学教育、技工学校教育、其他中等教育）；高等教育（大专、大学和研究生教育）'),
(230041, E'社会经济目标', E'非学历教育与培训', 230003, 2, 0, E'幼儿早期教育（幼儿园、其他幼儿启蒙教育）；技术教育和成人继续教育；在职教育与岗位培训；特殊教育（聋哑学校及其他特殊教育）；其他非学历教育与培训'),
(230042, E'社会经济目标', E'其他教育', 230003, 2, 0, E'识字扫盲、性教育等'),
(230043, E'社会经济目标', E'交通运输', 230004, 2, 0, E'交通规划；交通管理及交通安全；现代交通技术（综合交通智能化技术，实现综合交通运输服务、组织和控制的个性化、智能化和可视化）；交通运输设施建设与维护（包括铁路、公路、航空机场、港口等设施的建设与维护）；公路运输；铁路运输（包括铁路、地铁、轻轨）；水路运输；海运/远洋运输；航空运输；邮政；多种方式联运；其他方面的交通运输'),
